<section class="hero panel"><div><div class="eyebrow">Koko kalusto</div><h1>Kaikki huollot</h1><div class="sub"><?=count($allServices)?> huoltotapahtumaa kaikkien autojen yhteisessä aikajanassa.</div></div><div class="form-actions"><a class="btn" target="_blank" href="?print=all_history">🖨 Tulosta kaikki</a><a class="btn2" target="_blank" href="?print=all_history&photos=1">🖼 Kuvilla</a><a class="btn2" href="?export=all_xlsx">📊 Kaikki Exceliin</a></div></section>
<section class="section panel"><?php if(!$allServices):?><div class="empty">Huoltoja ei ole vielä kirjattu.</div><?php else:foreach($allServices as $s):?><details class="servicebox"><summary><div class="service-title"><div><strong><?=h(carName($s))?> · <?=h($s['title'])?></strong><?php if(($s['service_type']??'')&&$s['service_type']!==$s['title']):?> <span class="badge"><?=h($s['service_type'])?></span><?php endif;?><div class="tiny"><?=h(fiDate($s['service_date']))?> · <?=h(recordedKm((int)$s['odometer']))?><?=!empty($s['gap']['text'])?' · edellisestä huoltomerkinnästä '.h($s['gap']['text']):''?></div></div><span class="badge"><?=count($s['actions'])+count($s['custom_actions'])?> työtä<?=!empty($s['photos'])?' · 📷 '.count($s['photos']):''?></span></div></summary><div class="servicebody"><div class="chips"><?php foreach($s['actions'] as $a):?><span class="chip"><?=h($a['label'])?></span><?php endforeach;?><?php foreach($s['custom_actions'] as $a):?><span class="chip"><?=h($a['description'])?></span><?php endforeach;?></div><?php foreach($s['actions'] as $a):?><div class="kv"><span><?=h($a['label'])?></span><span><?=h(actionIntervalText($a))?></span></div><?php endforeach;?><?php if(!empty($s['mechanic_name_snapshot'])):?><div class="tiny" style="margin-top:9px">Mekaanikko: <?=h($s['mechanic_name_snapshot'])?></div><?php endif;?><?php if(!empty($s['photos'])):?><div class="photo-grid"><?php foreach($s['photos'] as $ph):?><div class="photo-card"><a href="<?=h(photoUrl((int)$ph['id'],'original'))?>" target="_blank"><img loading="lazy" src="<?=h(photoUrl((int)$ph['id'],'thumb'))?>" alt="Huoltokuva"></a><?php if(trim((string)($ph['caption']??''))!==''):?><div class="photo-caption"><?=h($ph['caption'])?></div><?php endif;?></div><?php endforeach;?></div><?php endif;?><div class="form-actions"><a class="btn2" href="?car=<?=(int)$s['car_id']?>&edit_service=<?=(int)$s['id']?>#huolto">✏ Muokkaa</a><a class="btn2" target="_blank" href="?print=service&service=<?=(int)$s['id']?>">🖨 Huoltosivu</a><?php if(!empty($s['photos'])):?><a class="btn2" target="_blank" href="?print=service&service=<?=(int)$s['id']?>&photos=1">🖼 Kuvilla</a><?php endif;?></div></div></details><?php endforeach;endif;?></section>
